turns.verify:
f={D}/exceptions.csv; test -f $f || { echo 'FAIL: no exceptions.csv'; exit 0; }
sed 's/^/SHOW /' $f | head -12
python3 - "$f" <<'EOF'
import re, sys
rows = [l for l in open(sys.argv[1]).read().splitlines() if l.strip()]
flagged = {}
for line in rows[1:]:
    m = re.search(r'R-\d', line)
    if not m:
        continue
    rule = re.search(r'\b([1-4])\b', line[m.end():])
    flagged[m.group(0)] = rule.group(1) if rule else '?'
want = {'R-2': '1', 'R-3': '3', 'R-4': '4', 'R-7': '2'}
print('SHOW flagged=' + ','.join(f'{k}:{v}' for k, v in sorted(flagged.items())))
missing = sorted(set(want) - set(flagged))
extra = sorted(set(flagged) - set(want))
wrong = sorted(k for k in want if k in flagged and flagged[k] not in ('?', want[k]))
if missing or extra or wrong:
    print(f'FAIL: missing={missing} wrongly_flagged={extra} wrong_rule={wrong}')
else:
    print('PASS')
EOF
